function canonicalExpenditureVariant(value){
  const v=String(value||'').trim().toLowerCase();
  if(v.includes('ganesh')||v.includes('festival')) return 'Ganesh Festival Fund';
  if(v.includes('colony')||v.includes('development')||v.includes('maintenance')) return 'Colony Fund';
  return String(value||'').trim()||'Colony Fund';
}
function expenditureVariantOf(row){return canonicalExpenditureVariant(row?.expenditureVariant||row?.fundType||row?.fund||row?.variant||row?.module||row?.expenseType||'');}
function expenditureCommittedOf(row){return Number(row?.amountCommitted??row?.committedAmount??row?.amount??row?.totalAmount??0)||0;}
function expenditureAdvanceOf(row){
  const direct=row?.advancePaid??row?.advance??row?.paidAmount??row?.amountPaid;
  if(direct!==undefined&&direct!==null&&String(direct)!=='') return Number(direct)||0;
  const committed=expenditureCommittedOf(row);
  return String(row?.paymentStatus||'').trim().toLowerCase()==='paid'?committed:0;
}
function normalizedExpenditure(row){
  const committed=expenditureCommittedOf(row), advance=Math.max(0,Math.min(committed||Infinity,expenditureAdvanceOf(row)));
  const description=String(row?.description||row?.particulars||row?.expenseHead||row?.item||'').trim();
  const variant=expenditureVariantOf(row);
  return {...row,expenditureVariant:variant,fundType:variant,description,particulars:description,amountCommitted:committed,amount:committed,totalAmount:committed,advancePaid:advance,amountDue:Math.max(0,committed-advance),balanceToBePaid:Math.max(0,committed-advance)};
}

