function syncExpenditureAdvanceLabel(){const label=document.getElementById('expenditureAdvanceLabel');if(label)label.textContent='Advance (₹)';}

function initializeReports(){
    const role=String(RGMS.auth.getSession()?.role||'');
    const reportType=document.getElementById('reportType');
    if(role==='Treasurer' && reportType){
      // Treasurer may generate financial reports and manage the shared Expenditure Register.
      [...reportType.options].forEach(o=>{o.hidden=!['fundSummary','development','festival','dailyLedger'].includes(o.value)&&!String(o.value).startsWith('cfg:');});
      if(!['fundSummary','development','festival','dailyLedger'].includes(reportType.value))reportType.value='fundSummary';
    }
    populateReportYears();
    populateReportFinancialYears();
    document.getElementById('reportPeriod')?.addEventListener('change',toggleCustomRange);
    document.getElementById('reportGenerate')?.addEventListener('click',generateReport);
    document.getElementById('reportExcel')?.addEventListener('click',exportExcel);
    document.getElementById('reportJpeg')?.addEventListener('click',()=>{exportJpeg().catch(e=>{console.error('JPEG export failed',e);rm(`Unable to export JPEG: ${e?.message||'Please try again.'}`,true);});});
    document.getElementById('reportPdf')?.addEventListener('click',printReport);
    document.getElementById('expenditureVariant')?.addEventListener('change',e=>{expenditureVariant=canonicalExpenditureVariant(e.target.value);e.target.value=expenditureVariant;syncExpenditureAdvanceLabel();renderExpenditureRegister();clearExpenditureForm();});
    document.getElementById('expenditureFY')?.addEventListener('change',e=>{expenditureFY=e.target.value;renderExpenditureRegister();clearExpenditureForm();});
    document.getElementById('expenditureSave')?.addEventListener('click',saveExpenditure);
    document.getElementById('expenditureUpdate')?.addEventListener('click',updateExpenditure);
    document.getElementById('expenditureDelete')?.addEventListener('click',deleteSelectedExpenditure);
    document.getElementById('expenditureClear')?.addEventListener('click',clearExpenditureForm);
    document.getElementById('expenditureRefresh')?.addEventListener('click',refreshExpenditures);
    document.getElementById('expenditureExcel')?.addEventListener('click',exportExpenditureExcel);
    document.getElementById('expenditurePrint')?.addEventListener('click',printExpenditureRegister);
    document.getElementById('expenditureSearch')?.addEventListener('input',renderExpenditureRegister);
    document.getElementById('expenditureRegisterVariant')?.addEventListener('change',e=>{expenditureRegisterVariant=String(e.target.value||'');renderExpenditureRegister();});
    document.getElementById('expenditureRegisterFY')?.addEventListener('change',e=>{expenditureRegisterFY=String(e.target.value||'');renderExpenditureRegister();});
    document.getElementById('expenditureAmount')?.addEventListener('input',calculateExpenditureBalance);
    document.getElementById('expenditureAdvance')?.addEventListener('input',calculateExpenditureBalance);
    if(!window.__rgReportDrillBound){window.__rgReportDrillBound=true;document.addEventListener('click',handleReportDrillClick);document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target?.matches?.('[data-report-drill],[data-report-main-drill]')){e.preventDefault();handleReportDrillClick(e);}});}
    populateExpenditureYears();
    applyExpenditurePermissions();
    syncExpenditureAdvanceLabel();
    toggleCustomRange();
    generateReport();
    loadExpenditureRegister();
}

function fyOptions(){
    const now=new Date();
    const start=now.getMonth()>=3?now.getFullYear():now.getFullYear()-1;
    return Array.from({length:7},(_,i)=>{const y=start-i;return `${y}-${String(y+1).slice(2)}`;});
}
function populateReportYears(){const now=new Date().getFullYear();const el=document.getElementById('reportYear');if(!el)return;el.innerHTML='';for(let y=now;y>=now-6;y--)el.insertAdjacentHTML('beforeend',`<option value="${y}">${y}</option>`);}
function populateReportFinancialYears(){const el=document.getElementById('reportFinancialYear');if(!el)return;const current=getFinancialYear();el.innerHTML=getFinancialYearOptions(6).map(y=>`<option value="${y}">${y}</option>`).join('');el.value=current;}
function populateExpenditureYears(){const years=fyOptions();const el=document.getElementById('expenditureFY');if(el){el.innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');el.value=expenditureFY;}const rf=document.getElementById('expenditureRegisterFY');if(rf){rf.innerHTML='<option value="">All Financial Years</option>'+years.map(y=>`<option value="${y}">${y}</option>`).join('');rf.value=expenditureRegisterFY;}}
function toggleCustomRange(){const p=document.getElementById('reportPeriod')?.value;const cr=document.getElementById('customRange');const ry=document.getElementById('reportYear');const fy=document.getElementById('reportFinancialYear');if(cr)cr.hidden=p!=='custom';if(ry)ry.disabled=p!=='year';if(fy)fy.disabled=p!=='currentFY';}
function range(){const p=document.getElementById('reportPeriod').value,now=new Date(),y=Number(document.getElementById('reportYear').value||now.getFullYear());if(p==='custom')return [document.getElementById('reportFrom').value||'1900-01-01',document.getElementById('reportTo').value||'2999-12-31','Custom Range'];if(p==='year')return [`${y}-01-01`,`${y}-12-31`,`${y}`];const fy=String(document.getElementById('reportFinancialYear')?.value||getFinancialYear());const parts=fy.split('-');const fyStart=Number(parts[0]);return [`${fyStart}-04-01`,`${fyStart+1}-03-31`,fy];}
function dateOf(r,type){if(type==='residents')return r.createdDate||'';if(type==='development'||type==='festival')return r.paymentDate||r.createdOn||'';if(type==='complaints')return r.complaintDate||r.createdOn||'';if(type==='visitors')return r.visitDate||r.createdOn||'';if(type==='meetings')return r.meetingDate||r.createdOn||'';if(type==='documents')return r.documentDate||r.uploadedOn||'';return '';}
async function getReportData(){const type=document.getElementById('reportType').value;const key={residents:STORAGE_KEYS.RESIDENTS,development:STORAGE_KEYS.DEVELOPMENT_FUND,festival:STORAGE_KEYS.GANESH_FESTIVAL,complaints:STORAGE_KEYS.COMPLAINTS,visitors:STORAGE_KEYS.VISITORS,meetings:STORAGE_KEYS.MEETINGS,documents:STORAGE_KEYS.DOCUMENTS}[type];await RGMS.store.loadCollection(key);const [from,to,label]=range();let rows=getAllRecords(key).filter(r=>{const d=String(dateOf(r,type)).slice(0,10);return !d||(d>=from&&d<=to);});rows=sortReportRowsByName(rows).map((r,i)=>({...r,sno:i+1}));return {type,rows,from,to,label};}
function normalizeRows(type){const maps={residents:[['S.No.','sno'],['Name','ownerName'],['H.No.','houseNo'],['Resident ID','residentId'],['Mobile','whatsapp'],['Status','status'],['Type','residentType']],development:[['S.No.','sno'],['Name','ownerName'],['H.No.','houseNo'],['Date','paymentDate'],['Amount','amountPaid'],['Receipt','receiptNo'],['Mode','paymentMode']],festival:[['S.No.','sno'],['Name','ownerName'],['H.No.','houseNo'],['Date','paymentDate'],['Amount','amountPaid'],['Payment Status','paymentStatus'],['Mode','paymentMode']],complaints:[['S.No.','sno'],['Name','residentName'],['H.No.','houseNo'],['No.','complaintNo'],['Date','complaintDate'],['Subject','subject'],['Category','category'],['Priority','priority'],['Status','status'],['Assigned To','assignedTo']],visitors:[['S.No.','sno'],['Resident Name','residentName'],['H.No.','houseNo'],['Date','visitDate'],['Visitor Name','visitorName'],['Mobile','visitorMobile'],['Purpose','purpose'],['Vehicle','vehicleNo'],['Entry','entryTime'],['Exit','exitTime']],meetings:[['S.No.','sno'],['Chairperson','chairperson'],['No.','meetingNo'],['Date','meetingDate'],['Time','meetingTime'],['Type','meetingType'],['Venue','venue'],['Status','status']],documents:[['S.No.','sno'],['Title','title'],['Date','documentDate'],['Category','category'],['File','fileName'],['Uploaded By','uploadedBy'],['Uploaded On','uploadedOn']]};return (maps[type]||[]).map(([h,k])=>[h,k]);}
function reportDisplayTitle(){const type=document.getElementById('reportType')?.value||'';if(type==='development')return 'Colony Fund Summary';if(type==='festival')return 'Ganesh Festival Fund Summary';if(type==='fundSummary')return 'Colony Fund + Ganesh Festival Collection Summary';return document.getElementById('reportType')?.options[document.getElementById('reportType').selectedIndex]?.text||'Report';}
function reportNameValue(r){return String(r?.ownerName||r?.residentName||r?.winnerName||r?.visitorName||r?.chairperson||r?.name||r?.title||'').trim();}
function sortReportRowsByName(rows){return (Array.isArray(rows)?rows:[]).slice().sort((a,b)=>reportNameValue(a).localeCompare(reportNameValue(b),'en',{sensitivity:'base',numeric:true})||String(a?.houseNo||a?.plotNo||'').localeCompare(String(b?.houseNo||b?.plotNo||''),undefined,{numeric:true}));}
function reportAsOnToday(){return new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'2-digit',year:'numeric'});}
function setReportAsOnToday(){const el=document.getElementById('reportPeriodLabel');if(el)el.textContent=reportAsOnToday();return reportAsOnToday();}

function currentFyMonthKeys(){
  const fy=getFinancialYear(); const now=new Date(); const m=String(getCollectionPeriod()).slice(0,7);
  const months=RGMS.getColonyFundMonthsForFY(fy,now); return {fy,month:m,months};
}
function paymentAmountR(p){return Number(p?.amountPaid??p?.paidAmount??p?.amount??0)||0;}
function paymentPaidR(p){const st=String(p?.paymentStatus||p?.status||'').trim().toLowerCase();return st==='paid'||(!st&&paymentAmountR(p)>=Number(DEFAULT_FUND_AMOUNT||500));}
function reportPeriodKeyR(r){return String(r?.collectionPeriod||r?.paymentDate||r?.date||r?.createdOn||'').slice(0,7);}
function reportFyOfPeriodR(period){if(!/^\d{4}-\d{2}$/.test(period))return '';const y=Number(period.slice(0,4)),m=Number(period.slice(5,7));return m>=4?`${y}-${String(y+1).slice(2)}`:`${y-1}-${String(y).slice(2)}`;}
function colonyExpensePeriodR(r){return String(r?.date||r?.paymentDate||r?.createdOn||'').slice(0,7);}
async function buildColonySummaryBilingual(){
  await Promise.all([RGMS.store.loadCollection(STORAGE_KEYS.RESIDENTS),RGMS.store.loadCollection(STORAGE_KEYS.DEVELOPMENT_FUND),RGMS.store.loadCollection(STORAGE_KEYS.EXPENDITURES)]);
  const residents=RGMS.store.getResidentMaster({includeVacant:true});
  const payments=getAllRecords(STORAGE_KEYS.DEVELOPMENT_FUND); const expenses=getAllRecords(STORAGE_KEYS.EXPENDITURES).map(normalizedExpenditure).filter(r=>expenditureVariantOf(r)==='Colony Fund');
  const {fy,month,months}=currentFyMonthKeys(); const monthlyAmount=Number(DEFAULT_FUND_AMOUNT||500);
  const house=RGMS.getAssociationHouseSummary(residents); const eligible=residents.filter(RGMS.isColonyFundEligibleOwner);
  const paidFor=(resident,period)=>{const matches=payments.filter(p=>RGMS.colonyFundPaymentMatchesResident(p,resident)&&RGMS.colonyFundPaymentPeriod(p)===period);const amt=matches.reduce((a,p)=>a+paymentAmountR(p),0);return matches.some(paymentPaidR)||amt>=monthlyAmount;};
  const expectedMonth=eligible.length*monthlyAmount; const expectedFY=eligible.length*monthlyAmount*months.length;
  const collectedMonth=eligible.reduce((sum,r)=>sum+(paidFor(r,month)?monthlyAmount:0),0);
  const collectedFY=eligible.reduce((sum,r)=>sum+months.reduce((x,m)=>x+(paidFor(r,m)?monthlyAmount:0),0),0);
  const expMonth=expenses.filter(e=>colonyExpensePeriodR(e)===month).reduce((a,e)=>a+expenditureAdvanceOf(e),0);
  const expFY=expenses.filter(e=>reportFyOfPeriodR(colonyExpensePeriodR(e))===fy).reduce((a,e)=>a+expenditureAdvanceOf(e),0);
  const pendingMonth=Math.max(0,expectedMonth-collectedMonth), pendingFY=Math.max(0,expectedFY-collectedFY);
  return {fy,month,monthLabel:new Date(Number(month.slice(0,4)),Number(month.slice(5,7))-1,1).toLocaleDateString('en-IN',{month:'long',year:'numeric'}),
    totalHouses:house.totalHouses,occupied:house.occupiedHouses,vacant:house.vacantHouses,
    expectedFY,collectedFY,pendingFY,expenditureFY:expFY,balanceFY:collectedFY-expFY,
    expectedMonth,collectedMonth,pendingMonth,expenditureMonth:expMonth,balanceMonth:collectedMonth-expMonth};
}
function bilingualLabel(te,en){return `<span class="rg-te">${escR(te)}</span><span class="rg-en">${escR(en)}</span>`;}
