  getAllRecords(STORAGE_KEYS.DEVELOPMENT_FUND).forEach(r=>{const d=r.paymentDate||r.createdOn;if(inRange(d))rows.push({date:String(d).slice(0,10),particulars:`Colony Fund - ${formatHNo(r.houseNo||r.plotNo||'')} ${r.ownerName||''}`.trim(),type:'Collection',fundType:'Colony Fund',amount:Number(r.amountPaid||r.amount||0)});});
