  getAllRecords(STORAGE_KEYS.FESTIVAL_FUND).forEach(r=>{const d=r.paymentDate||r.createdOn;if(inRange(d))rows.push({date:String(d).slice(0,10),particulars:`Ganesh Chanda - ${formatHNo(r.houseNo||r.plotNo||'')} ${r.ownerName||''}`.trim(),type:'Collection',fundType:'Ganesh Festival',amount:Number(r.amountPaid||0)});});
  getAllRecords(STORAGE_KEYS.EXPENDITURES).map(normalizedExpenditure).forEach(r=>{const d=r.date||r.createdOn;if(inRange(d))rows.push({date:String(d).slice(0,10),particulars:r.description||r.particulars||r.voucherNo||'Expenditure',type:'Expenditure',fundType:expenditureVariantOf(r),amount:expenditureAdvanceOf(r)});});
