function removeGaneshReportSummary(){document.getElementById('ganeshReportSummary')?.remove();document.getElementById('ledgerReportSummary')?.remove();document.getElementById('configuredReportSummary')?.remove();}
function resolveReportValue(row,key){
  if(!row||typeof row!=='object')return '';
  if(row[key]!==undefined&&row[key]!==null&&String(row[key])!=='')return row[key];
  const aliases={
    sno:['sno','serialNo','serialNumber','sNo'], serialNo:['serialNo','sno','serialNumber','sNo'],
    plotNo:['plotNo','houseNo','hNo','hno'], houseNo:['houseNo','plotNo','hNo','hno'],
    ownerName:['ownerName','residentName','name','winnerName'], residentName:['residentName','ownerName','name'],
    amountPaid:['amountPaid','amount','chandaAmount','paidAmount','auctionAmount','cashContributionAmount','totalAmountPaid'],
    chandaAmount:['chandaAmount','cashContributionAmount','amountPaid','paidAmount','amount'], cashContributionAmount:['cashContributionAmount','sponsorCashContribution','contributionAmount','chandaAmount','amountPaid','paidAmount','amount'], amount:['amount','amountPaid','chandaAmount','cashContributionAmount','auctionAmount','totalAmount','totalAmountPaid'],
    paymentStatus:['paymentStatus','status'], status:['status','paymentStatus'],
    paymentMode:['paymentMode','mode'], paymentDate:['paymentDate','dateOfPayment','date','auctionDate','createdOn'],
    residentId:['residentId','winnerResidentId'], remarks:['remarks','remark','notes'],
    auctionAmount:['auctionAmount','ladduAmount','amountPaid','amount'], winnerName:['winnerName','ownerName','residentName','name'], winnerResidentId:['winnerResidentId','residentId'],
    expenditureVariant:['expenditureVariant','fundType','fund','variant','module','expenseType'],
    description:['description','particulars','expenseHead','item'], particulars:['particulars','description','expenseHead','item'],
    amountCommitted:['amountCommitted','committedAmount','amount','totalAmount'],
    advancePaid:['advancePaid','advance','paidAmount','amountPaid'],
    amountDue:['amountDue','balanceToBePaid','balance','dueAmount'], balanceToBePaid:['balanceToBePaid','amountDue','balance','dueAmount']
  };
  const candidates=aliases[key]||[key];
  for(const k of candidates){if(row[k]!==undefined&&row[k]!==null&&String(row[k])!=='')return row[k];}
  const norm=v=>String(v||'').toLowerCase().replace(/[\s_.-]/g,'');
  const wanted=candidates.map(norm);for(const k of Object.keys(row)){if(wanted.includes(norm(k))&&row[k]!==undefined&&row[k]!==null&&String(row[k])!=='')return row[k];}
  return '';
}
function reportCellValue(row,key){const value=resolveReportValue(row,key);if(key==='houseNo'||key==='plotNo')return formatHNo(value||'');if(['amountPaid','amount','chandaAmount','cashContributionAmount','auctionAmount','totalCY','totalTill','totalDue','totalPaid','totalAmountPaid','advancePaid','amountCommitted','amountDue','balanceToBePaid',...Array.from({length:12},(_,i)=>`m${String(i+1).padStart(2,'0')}`),'toBePaidAmount','pendingAmount','expectedAmount','balanceDue'].includes(key))return formatCurrency(Number(value||0));return value??'';}
function escR(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function rgBase64Utf8(text){return btoa(unescape(encodeURIComponent(String(text||''))));}
function rgBlobFromBase64(base64,mimeType){
  const bytes=atob(String(base64||''));
  const out=new Uint8Array(bytes.length);
  for(let i=0;i<bytes.length;i++)out[i]=bytes.charCodeAt(i);
  return new Blob([out],{type:mimeType||'application/octet-stream'});
}
function rgDownloadBlob(blob,fileName){
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=fileName||'Rose_Gardens_Report';
  document.body.appendChild(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1500);
}
function rgOpenWhatsAppReport(title,fileName,extra=''){
  const msg=[`Rose Gardens report: ${title||'Report'}.`,fileName?`File: ${fileName}.`:'',extra].filter(Boolean).join(' ');
  const url=`https://wa.me/?text=${encodeURIComponent(msg)}`;
  const w=window.open(url,'_blank','noopener,noreferrer');
  if(!w)window.location.href=url;
}
async function rgShareFileToWhatsAppWeb(blob,fileName,mimeType,title){
  try{
    const file=new File([blob],fileName,{type:mimeType||blob.type||'application/octet-stream'});
    if(navigator.share && navigator.canShare && navigator.canShare({files:[file]})){
      await navigator.share({title:title||'Rose Gardens Report',text:`Rose Gardens report: ${title||fileName}`,files:[file]});
      return true;
    }
  }catch(e){
    if(e?.name==='AbortError')return true;
    console.warn('Web file share unavailable; using WhatsApp Web fallback.',e);
  }
  try{
    rgDownloadBlob(blob,fileName);
    rgOpenWhatsAppReport(title,fileName,'The report has been downloaded. Please attach the downloaded file in WhatsApp.');
    return true;
  }catch(e){
    console.error('WhatsApp Web fallback failed.',e);
    return false;
  }
}
