  if(isColony){const monthly=JSON.parse(document.getElementById('reportTable')?.dataset.monthlyTotals||'{}');const monthTotalY=tableTop+headerHTable+Math.max(rows.length,1)*rowH;let xx=x0;for(let ci=0;ci<cols.length;ci++){const w=widths[ci];ctx.fillStyle='#e8eef7';ctx.fillRect(xx,monthTotalY,w,rowH);ctx.strokeStyle='#aeb7c2';ctx.strokeRect(xx,monthTotalY,w,rowH);ctx.fillStyle='#123f78';ctx.font='bold 12px Arial';ctx.textAlign='center';let val='';if(ci===2)val='Monthly Totals';else if(ci>=colonyMonthStart&&ci<=colonyMonthEnd)val=formatCurrency(monthly[cols[ci][1]]||0);else if(ci===colonyTotalIndex)val=formatCurrency(Number(document.getElementById('reportTable')?.dataset.paidAmount||0));ctx.fillText(val,xx+w/2,monthTotalY+25);xx+=w;}const sumY=monthTotalY+rowH+28;const boxW=reportW-32;const cardW=(boxW-20)/3;const tableEl=document.getElementById('reportTable');const dExpected=Number(tableEl?.dataset.expectedAmount||0);const dPaid=Number(tableEl?.dataset.paidAmount||rows.reduce((s,r)=>s+Number(r.totalAmountPaid||0),0));const dDue=Number(tableEl?.dataset.dueAmount||Math.max(0,dExpected-dPaid));[['Grand Total Expected',dExpected],['Grand Total Paid',dPaid],['Grand Total Due',dDue]].forEach((it,i)=>{const sx=contentX+16+i*(cardW+10);ctx.fillStyle='#fff';ctx.strokeStyle='#123f78';ctx.lineWidth=1.5;ctx.fillRect(sx,sumY,cardW,58);ctx.strokeRect(sx,sumY,cardW,58);ctx.fillStyle='#123f78';ctx.font='bold 14px Arial';ctx.textAlign='center';ctx.fillText(it[0],sx+cardW/2,sumY+22);ctx.fillStyle='#222';ctx.font='bold 16px Arial';ctx.fillText(formatCurrency(it[1]),sx+cardW/2,sumY+45);});}
