function showReportFilteredRegister(title,headers,rowHtml,emptyText='No matching records found.'){
  document.getElementById('reportFilteredRegister')?.remove();
  const tableWrap=document.getElementById('reportTable')?.closest('.table-wrap');if(!tableWrap)return;
  const sec=document.createElement('section');sec.id='reportFilteredRegister';sec.className='form-card report-filtered-register rg-filter-overlay'; document.body.classList.add('rg-filter-screen-open');
  sec.innerHTML=`<div class="rg-filtered-register-head"><h3>${escR(title)}</h3><button type="button" class="btn btn-secondary btn-sm" data-close-report-drill>Close</button></div><div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${escR(h)}</th>`).join('')}</tr></thead><tbody>${rowHtml||`<tr><td colspan="${headers.length}" class="empty">${escR(emptyText)}</td></tr>`}</tbody></table></div>`;
  tableWrap.parentElement.insertBefore(sec,tableWrap);sec.scrollIntoView({behavior:'smooth',block:'start'});
}
function contributionRowsHtml(rows){return sortReportRowsByName(rows).map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.ownerName||'')}</td><td>${escR(formatHNo(r.plotNo||r.houseNo||''))}</td><td>${formatCurrency(r.amount||0)}</td><td>${escR(r.paymentStatus||'')}</td><td>${escR(r.paymentDate||'')}</td><td>${escR(r.remarks||'')}</td></tr>`).join('');}
function expenseRowsHtml(rows,directRequired=false){return rows.map((r,i)=>{const projected=expenditureCommittedOf(r),incurred=expenditureAdvanceOf(r),required=directRequired?(projected-incurred):Math.max(0,projected-incurred);return `<tr><td>${i+1}</td><td>${escR(r.description||r.particulars||'')}</td><td>${formatCurrency(projected)}</td><td>${formatCurrency(incurred)}</td><td>${formatCurrency(required)}</td><td>${escR(r.remarks||'')}</td></tr>`;}).join('');}
function handleReportDrillClick(e){
  const close=e.target?.closest?.('[data-close-report-drill]');if(close){document.getElementById('reportFilteredRegister')?.remove();document.body.classList.remove('rg-filter-screen-open');return;}
  const el=e.target?.closest?.('[data-report-drill],[data-report-main-drill]');if(!el)return;
  e.preventDefault();e.stopPropagation();
  const key=el.dataset.reportDrill||el.dataset.reportMainDrill||'';
  if(key.startsWith('ganesh-')&&lastGaneshReportData){const d=lastGaneshReportData;
    if(key==='ganesh-sponsors')return showReportFilteredRegister('Ganesh Festival - Sponsors',['S.No.','Name','H.No.','Sponsor Type','Cash Contribution','Payment Status'],sortReportRowsByName(d.sponsorRows||[]).map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.ownerName||'')}</td><td>${escR(formatHNo(r.plotNo||r.houseNo||''))}</td><td>${escR(r.sponsorType||'')}</td><td>${formatCurrency(r.cashContributionAmount||0)}</td><td>${escR((r.cashContributionAmount||0)>0?(r.paymentStatus||'Unpaid'):'—')}</td></tr>`).join(''));
    if(key==='ganesh-paid')return showReportFilteredRegister('Ganesh Festival - Total Contributions Paid',['S.No.','Name','H.No.','Amount','Payment Status','Date of Payment','Remarks'],contributionRowsHtml(d.rows.filter(r=>String(r.paymentStatus||'').trim().toLowerCase()==='paid')));
    if(key==='ganesh-expected')return showReportFilteredRegister('Ganesh Festival - Expected Contributions',['S.No.','Name','H.No.','Amount','Payment Status','Date of Payment','Remarks'],contributionRowsHtml(d.rows.filter(r=>{const st=String(r.paymentStatus||'').trim().toLowerCase();return st==='paid'||st==='to be paid';})));
    if(key==='ganesh-due')return showReportFilteredRegister('Ganesh Festival - Contributions Due',['S.No.','Name','H.No.','Amount','Payment Status','Date of Payment','Remarks'],contributionRowsHtml(d.rows.filter(r=>String(r.paymentStatus||'').trim().toLowerCase()==='to be paid')));
    if(key==='ganesh-laddu'){const rows=sortReportRowsByName((d.auctionRows||[]).filter(r=>String(r.paymentStatus||'Unpaid').trim().toLowerCase()==='paid'));return showReportFilteredRegister('Ganesh Festival - Laddu Auction Amount',['S.No.','Winner Name','H.No.','Laddu Amount','Payment Status','Auction Date','Remarks'],rows.map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.winnerName||'')}</td><td>${escR(formatHNo(r.houseNo||r.winnerPlotNo||''))}</td><td>${formatCurrency(r.auctionAmount||0)}</td><td>${escR(r.paymentStatus||'Paid')}</td><td>${escR(r.auctionDate||'')}</td><td>${escR(r.remarks||'')}</td></tr>`).join(''));}
    if(key==='ganesh-grand'){const paid=d.rows.filter(r=>String(r.paymentStatus||'').trim().toLowerCase()==='paid').map(r=>({type:'Contribution',hno:r.plotNo,name:r.ownerName,amount:r.amount,date:r.paymentDate,remarks:r.remarks}));const laddu=(d.auctionRows||[]).filter(r=>String(r.paymentStatus||'Unpaid').trim().toLowerCase()==='paid').map(r=>({type:'Laddu Auction',hno:r.houseNo||r.winnerPlotNo,name:r.winnerName,amount:r.auctionAmount,date:r.auctionDate,remarks:r.remarks}));const rows=[...paid,...laddu].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'en',{sensitivity:'base'}));return showReportFilteredRegister('Ganesh Festival - Total Festival Fund Details',['S.No.','Name','H.No.','Type','Amount','Date','Remarks'],rows.map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.name||'')}</td><td>${escR(formatHNo(r.hno||''))}</td><td>${escR(r.type)}</td><td>${formatCurrency(r.amount||0)}</td><td>${escR(r.date||'')}</td><td>${escR(r.remarks||'')}</td></tr>`).join(''));}
    if(['ganesh-incurred','ganesh-advance','ganesh-projected','ganesh-committed'].includes(key)){
      const title=(key==='ganesh-incurred'||key==='ganesh-advance')?'Ganesh Festival - Advance':'Ganesh Festival - Amount';
      return showReportFilteredRegister(title,['S.No.','Description','Amount','Advance','Balance to be paid','Remarks'],expenseRowsHtml(d.expenseRows||[]));
    }
    if(key==='ganesh-balance'||key==='ganesh-required'){
      const projected=d.projectedExpenditure??d.totalAmountCommitted??0;
      const incurred=d.expenditureIncurred??d.expenditure??d.amountSpent??d.totalAdvancePaid??0;
      const fund=d.totalFestivalFund??d.grandTotal??0;
      const balance=d.balance??d.balanceAmount??(fund-incurred);
      const amountRequired=d.amountRequired??((projected-incurred)-balance);
      const rows=[['Amount',projected],['Advance',incurred],['Balance to be paid',Math.max(0,projected-incurred)],['Total Festival Fund',fund],['Balance',balance],['Amount Required',amountRequired]];
      return showReportFilteredRegister(key==='ganesh-balance'?'Ganesh Festival - Balance Calculation':'Ganesh Festival - Amount Required Calculation',['S.No.','Description','Amount'],rows.map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r[0])}</td><td>${formatCurrency(r[1]||0)}</td></tr>`).join(''));
    }
  }
  if(key.startsWith('colony-')&&lastColonyReportData){const d=lastColonyReportData;
    if(key==='colony-expenditure')return showReportFilteredRegister('Colony Fund - Expenditure Register',['S.No.','Description','Amount','Advance','Balance to be paid','Remarks'],expenseRowsHtml(d.expenseRows||[]));
    return showReportFilteredRegister(key==='colony-balance'?'Colony Fund - Balance Supporting Register':'Colony Fund - Contribution Register',['S.No.','Name','H.No.','Total Amount Paid','Pending Amount','Remarks'],sortReportRowsByName(d.rows||[]).map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.ownerName||'')}</td><td>${escR(formatHNo(r.plotNo||''))}</td><td>${formatCurrency(r.totalAmountPaid||0)}</td><td>${formatCurrency(r.pendingAmount||0)}</td><td>${escR(r.remarks||'')}</td></tr>`).join(''));
  }
  const type=document.getElementById('reportType')?.value||'';
  if(type==='festival'&&lastGaneshReportData)return showReportFilteredRegister('Ganesh Festival - Report Records',['S.No.','Name','H.No.','Amount','Payment Status','Date of Payment','Remarks'],contributionRowsHtml(lastGaneshReportData.rows||[]));
  if(type==='development'&&lastColonyReportData)return showReportFilteredRegister('Colony Fund - Report Records',['S.No.','Name','H.No.','Total Amount Paid','Pending Amount','Remarks'],sortReportRowsByName(lastColonyReportData.rows||[]).map((r,i)=>`<tr><td>${i+1}</td><td>${escR(r.ownerName||'')}</td><td>${escR(formatHNo(r.plotNo||''))}</td><td>${formatCurrency(r.totalAmountPaid||0)}</td><td>${formatCurrency(r.pendingAmount||0)}</td><td>${escR(r.remarks||'')}</td></tr>`).join(''));
  const cols=reportColumns.length?reportColumns:[['S.No.','sno']];showReportFilteredRegister('Filtered Report Register',cols.map(c=>c[0]),reportRows.map(r=>`<tr>${cols.map(([,k])=>`<td>${escR(reportCellValue(r,k))}</td>`).join('')}</tr>`).join(''));
}

