function calculateExpenditureBalance(){const committed=Number(document.getElementById('expenditureAmount')?.value||0),advance=Math.max(0,Number(document.getElementById('expenditureAdvance')?.value||0)),due=Math.max(0,committed-advance);const el=document.getElementById('expenditureBalance');if(el)el.value=due.toFixed(2);return due;}
function expenditureForm(){const committed=Number(document.getElementById('expenditureAmount').value||0),advancePaid=Math.max(0,Number(document.getElementById('expenditureAdvance')?.value||0)),variant=canonicalExpenditureVariant(document.getElementById('expenditureVariant').value),description=document.getElementById('expenditureParticulars').value.trim(),due=Math.max(0,committed-advancePaid);return {voucherNo:document.getElementById('expenditureVoucher').value.trim(),date:document.getElementById('expenditureDate').value,financialYear:document.getElementById('expenditureFY').value,expenditureVariant:variant,fundType:variant,description,particulars:description,amountCommitted:committed,amount:committed,totalAmount:committed,advancePaid,amountDue:due,balanceToBePaid:due,paymentStatus:due<=0?'Paid':'Pending',remarks:document.getElementById('expenditureRemarks').value.trim()};}
