async function updateExpenditure(){if(!canExpenditure('update'))return em('This role does not have permission to update expenditure.',true);if(!selectedExpenditureId)return em('Click View on a register row before Update.',true);const old=expenditureRows.find(x=>String(x.id)===String(selectedExpenditureId));const r={...old,...expenditureForm(),updatedOn:new Date().toISOString(),updatedBy:RGMS.auth.getSession()?.email||RGMS.auth.getSession()?.role||''};if(!r.date||!r.description||r.amountCommitted<=0)return em('Date, Description and Amount are required.',true);if(r.advancePaid>r.amountCommitted)return em('Advance cannot exceed Amount.',true);try{await RGMS.store.setRecord(STORAGE_KEYS.EXPENDITURES,selectedExpenditureId,r);em('Expenditure updated successfully.');await refreshExpenditures();clearExpenditureForm();}catch(e){console.error(e);em('Unable to update expenditure.',true);}}
