function selectExpenditure(id){const r=expenditureRows.find(x=>String(x.id)===String(id));if(!r)return;selectedExpenditureId=r.id;expenditureVariant=expenditureVariantOf(r);expenditureFY=r.financialYear||getFinancialYear(r.date||r.createdOn);document.getElementById('expenditureVoucher').value=r.voucherNo||'';document.getElementById('expenditureDate').value=String(r.date||'').slice(0,10);const fyEl=document.getElementById('expenditureFY');if(fyEl){if(![...fyEl.options].some(o=>o.value===expenditureFY))fyEl.insertAdjacentHTML('beforeend',`<option value="${escR(expenditureFY)}">${escR(expenditureFY)}</option>`);fyEl.value=expenditureFY;}document.getElementById('expenditureVariant').value=expenditureVariant;syncExpenditureAdvanceLabel();document.getElementById('expenditureParticulars').value=r.description||r.particulars||'';document.getElementById('expenditureAmount').value=expenditureCommittedOf(r)||'';document.getElementById('expenditureAdvance').value=expenditureAdvanceOf(r)||0;calculateExpenditureBalance();document.getElementById('expenditureRemarks').value=r.remarks||'';em('Expenditure selected. Use Update or Delete to change this Firebase record.');document.getElementById('expenditureRegisterSection')?.scrollIntoView({behavior:'smooth',block:'start'});}
