window.deleteExpenditureById=deleteExpenditureById;window.selectExpenditure=selectExpenditure;
function clearExpenditureForm(){selectedExpenditureId=null;const set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v;};set('expenditureVoucher',nextVoucher());set('expenditureDate',new Date().toISOString().slice(0,10));set('expenditureFY',expenditureFY);set('expenditureVariant',canonicalExpenditureVariant(expenditureVariant));set('expenditureParticulars','');set('expenditureAmount','');set('expenditureAdvance','');set('expenditureBalance','');set('expenditureRemarks','');syncExpenditureAdvanceLabel();}
