  tbody.innerHTML=rows.map((r,i)=>{
    const projected=expenditureCommittedOf(r),incurred=expenditureAdvanceOf(r),required=Math.max(0,projected-incurred);
    return `<tr><td>${i+1}</td><td>${escR(r.description||r.particulars||'')}</td><td>${formatCurrency(projected)}</td><td>${formatCurrency(incurred)}</td><td>${formatCurrency(required)}</td><td>${escR(r.remarks||'')}</td><td><div class="rg-grid-actions"><button class="rg-icon-btn rg-view" type="button" title="View expenditure" onclick="selectExpenditure('${escR(r.id)}')">👁️ View</button>${canExpenditure('update')?`<button class="rg-icon-btn rg-update" type="button" title="Edit expenditure" onclick="selectExpenditure('${escR(r.id)}')">✏️ Edit</button>`:''}${canExpenditure('delete')?`<button class="rg-icon-btn rg-delete" type="button" title="Delete expenditure" onclick="deleteExpenditureById('${escR(r.id)}')">🗑️ Delete</button>`:''}</div></td></tr>`;
  }).join('')||'<tr><td colspan="7" class="empty">No expenditure records for the selected variant and financial year.</td></tr>';
